package com.quincaisoft.commerce.web;import com.quincaisoft.commerce.api.CommerceService;import org.springframework.web.bind.annotation.*;import org.springframework.security.access.prepost.PreAuthorize;import java.util.*;
@RestController @RequestMapping("/api/v1/commerce") @PreAuthorize("hasAnyAuthority('commerce:manage','SCOPE_commerce:manage')") public class CommerceController{private final CommerceService service;public CommerceController(CommerceService service){this.service=service;}@GetMapping("/store")public CommerceService.StoreView store(){return service.store();}@PostMapping("/store")public CommerceService.StoreView configure(@RequestHeader("Idempotency-Key")UUID operation,@RequestBody CommerceService.Configure c){if(!operation.equals(c.operationId()))throw new IllegalArgumentException("Operation mismatch");return service.configure(c);}@GetMapping("/listings")public List<CommerceService.ListingView> listings(){return service.listings();}@PostMapping("/listings")public CommerceService.ListingView publish(@RequestHeader("Idempotency-Key")UUID operation,@RequestBody CommerceService.Publish c){if(!operation.equals(c.operationId()))throw new IllegalArgumentException("Operation mismatch");return service.publish(c);}}
